package com.autoops.auth.entity;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="refresh_tokens") public class RefreshToken{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="user_id",nullable=false)private Long userId;@Column(name="token_hash",nullable=false,unique=true)private String tokenHash;@Column(name="expires_at",nullable=false)private Instant expiresAt;@Column(name="revoked_at")private Instant revokedAt;@Column(name="created_at",nullable=false)private Instant createdAt=Instant.now();public Long getId(){return id;}public Long getUserId(){return userId;}public void setUserId(Long v){userId=v;}public String getTokenHash(){return tokenHash;}public void setTokenHash(String v){tokenHash=v;}public Instant getExpiresAt(){return expiresAt;}public void setExpiresAt(Instant v){expiresAt=v;}public Instant getRevokedAt(){return revokedAt;}public void setRevokedAt(Instant v){revokedAt=v;}}
